protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long maxDuration = FETCH_DATA_DURATION;
    if (maxDuration <= 0) {
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    long currentStart = start;
    while (currentStart < end) {
        long next;
        try {
            next = Math.addExact(currentStart, maxDuration);
        } catch (ArithmeticException e) {
            next = Long.MAX_VALUE;
        }
        if (next > end || next < currentStart) {
            next = end;
        }
        ranges.add(new TimeRange(currentStart, next));
        currentStart = next;
    }
    return ranges;
}

