public void removeFromTreeEdgeList() {
    // Remove this edge from the source node's outgoing edge list
    if (prev != null) {
        prev.next = next;
    } else if (source != null) {
        source.firstEdge = next;
    }
    if (next != null) {
        next.prev = prev;
    } else if (source != null) {
        source.lastEdge = null;
    }

    // Remove this edge from the target node's incoming edge list
    if (prevSibling != null) {
        prevSibling.nextSibling = nextSibling;
    } else if (target != null) {
        target.firstEdge = nextSibling;
    }
    if (nextSibling != null) {
