public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // Ensure candidate is odd (except 2)
    if (candidate % 2 == 0) {
        candidate++;
    }
    // Optional: limit search to within 11% if desiredCapacity >= 1000
    int maxCandidate = desiredCapacity;
    if (desiredCapacity >= 1000) {
        maxCandidate = (int) (desiredCapacity * 1.11) + 1;
    }
    while (candidate > 0) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2;
        // If we exceed Integer.MAX_VALUE, break
        if (candidate < 0) {
            break;
        }
        // If we exceed the 11% limit, we still return the next prime found
        if (candidate > maxCandidate && desiredCapacity >= 1000) {
            // Continue searching; the next prime will be returned anyway
            // This condition is just to avoid infinite loops in pathological cases
            // but we still return the prime found
            // No action needed here
            ;
        }
    }
    // Fallback: return Integer.MAX_VALUE if no prime found (unlikely)
    return Integer.MAX_VALUE;
}

private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    int i = 5;
    int w = 2;
    while (i * i <= n) {
        if (n % i == 0) return false;
        i += w;
        w = 6 - w;
    }
    return true;
}

