private static int digitValue(final char c) {
    // ASCII digits 0-9
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    // ASCII uppercase letters A-Z
    if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    }
    // ASCII lowercase letters a-z
    if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    }
    // Not a valid ASCII digit or letter
    return -1;
}

