final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    try {
        // Find the offset of the CONSTANT_Utf8 entry in the class file buffer
        int entryOffset = getConstantPoolEntryOffset(constantPoolEntryIndex);
        // The entry starts with a tag byte (1 for CONSTANT_Utf8), followed by a 2‑byte length
        int length = ((classFileBuffer[entryOffset + 1] & 0xFF) << 8) | (classFileBuffer[entryOffset + 2] & 0xFF);
        if (charBuffer == null || charBuffer.length < length) {
            throw new IllegalArgumentException("Provided charBuffer is too small for the UTF‑8 string");
        }
        // Copy the UTF‑8 bytes into a temporary array
        byte[] bytes = new byte[length];
        System.arraycopy(classFileBuffer, entryOffset + 3, bytes, 0, length);
        // Decode the bytes into a String
        String result = new String(bytes, java.nio.charset.Charset.forName("UTF-8"));
        // Copy the decoded characters into the supplied buffer
        System.arraycopy(result.toCharArray(), 0, charBuffer, 0, result.length());
        return result;
    } catch (ArrayIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid constant pool index or corrupted class file", e);
    }
}

