public static long factorial(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    long result = 1L;
    for (int i = 2; i <= n; i++) {
        if (result > Long.MAX_VALUE / i) {
            throw new ArithmeticException("long overflow");
        }
        result *= i;
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node must not be null");
    }

    // Create a circulator starting at the given node and direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // If the starting node already satisfies the predicate, return immediately.
    if (predicate.test(circ.getNode())) {
        return circ;
    }

    // Traverse until we reach the stop node or find a node that satisfies the predicate.
    while (!circ.getNode().equals(stop)) {
        circ.next(); // Move to the next node in the specified direction.
        if (predicate.test(circ.getNode())) {
            break;
        }
    }

    // Return the circulator positioned at the node that satisfies the predicate
    // or at the stop node if none was found.
    return circ;
}

