public double vertexWeight(Set<V> v){
    if (v == null) return 0.0;
    double sum = 0.0;
    try {
        for (V vertex : v) {
            if (vertex == null) continue;
            for (Edge e : getIncomingEdges(vertex)) {
                if (e != null) sum += e.weight();
            }
        }
    } catch (Exception e) {
        return 0.0;
    }
