protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return null;
    }
    // Build adjacency
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        if (e == null) {
            throw new IllegalArgumentException("edge in tour is null");
        }
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        if (src == null || tgt == null) {
            throw new IllegalArgumentException("edge source or target is null");
        }
        adjacency.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
    }
    // Validate degree
    for (Map.Entry<V, List<E>> entry : adjacency.entrySet()) {
        if (entry.getValue().size() != 2) {
            throw new IllegalArgumentException("vertex " + entry.getKey() + " does not have degree 2");
        }
    }
    // Start traversal
    V start = adjacency.keySet().iterator().next();
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> visited = new HashSet<>();
    V current = start;
    E prevEdge = null;
    while (true) {
        vertexList.add(current);
        List<E> edges = adjacency.get(current);
        E nextEdge = null;
        for (E e : edges) {
            if (!e.equals(prevEdge) && !visited.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            break;
        }
        edgeList.add(nextEdge);
        visited.add(nextEdge);
        V nextVertex = graph.getEdgeSource(nextEdge).equals(current) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        prevEdge = nextEdge;
        current = nextVertex;
        if (current.equals(start)) {
            // Completed cycle
            break;
        }
    }
    if (edgeList.size() != tour.size()) {
        throw new IllegalArgumentException("edges do not form a single tour");
    }
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }
    return new org.jgrapht.graph.GraphPathImpl<>(graph, start, start, edgeList, vertexList, weight);
}
