private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(input.length());
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        // Escape sequence
        if (i + 1 >= len) {
            // Trailing backslash, treat as literal
            sb.append('\\');
            break;
        }
        char next = input.charAt(i + 1);
        switch (next) {
            case 'n':
                sb.append('\n');
                i += 1;
                break;
            case 't':
                sb.append('\t');
                i += 1;
                break;
            case 'r':
                sb.append('\r');
                i += 1;
                break;
            case 'b':
                sb.append('\b');
                i += 1;
                break;
            case 'f':
                sb.append('\f');
                i += 1;
                break;
            case 'v':
                sb.append('\u000B'); // vertical tab
                i += 1;
                break;
            case '0':
                sb.append('\0');
                i += 1;
                break;
            case '\\':
                sb.append('\\');
                i += 1;
                break;
            case '\'':
                sb.append('\'');
                i += 1;
                break;
            case '\"':
                sb.append('\"');
                i += 1;
                break;
            case '?':
                sb.append('?');
                i += 1;
                break;
            case 'a':
                sb.append('\u0007'); // bell
                i += 1;
                break;
            case 'e':
                sb.append('\u001B'); // escape
                i += 1;
                break;
            case 'c':
                sb.append('\u0018'); // cancel
                i += 1;
                break;
            case 'x':
                // Hex escape \xNN
                if (i + 3 < len) {
                    String hex = input.substring(i + 2, i + 4);
                    try {
                        int val = Integer.parseInt(hex, 16);
                        sb.append((char) val);
                        i += 3;
                    } catch (NumberFormatException e) {
                        // Invalid hex, treat literally
                        sb.append('\\').append('x');
                        i += 1;
                    }
                } else {
                    sb.append('\\').append('x');
                    i += 1;
                }
                break;
            case 'u':
                // Unicode escape \uNNNN
                if (i + 5 < len) {
                    String hex = input.substring(i + 2, i + 6);
                    try {
                        int val = Integer.parseInt(hex, 16);
                        sb.append((char) val);
                        i += 5;
                    } catch (NumberFormatException e) {
                        sb.append('\\').append('u');
                        i += 1;
                    }
                } else {
                    sb.append('\\').append('u');
                    i += 1;
                }
                break;
            default:
                // Check for octal escape \NNN (up to 3 digits)
                if (next >= '0' && next <= '7') {
                    int j = i + 1;
                    int end = j;
                    while (end < len && end - j < 3 && input.charAt(end) >= '0' && input.charAt(end) <= '7') {
                        end++;
                    }
                    String oct = input.substring(j, end);
                    try {
                        int val = Integer.parseInt(oct, 8);
                        sb.append((char) val);
                        i = end - 1;
                    } catch (NumberFormatException e) {
                        sb.append('\\').append(next);
                        i += 1;
                    }
                } else {
                    // Unrecognized escape, keep the next character
                    sb.append(next);
                    i += 1;
                }
                break;
        }
    }
    return sb.toString();
}

