private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    try {
        ListNodeImpl<E> prev = node.prev;
        ListNodeImpl<E> next = node.next;
        if (prev != null) {
            prev.next = next;
        }
        if (next != null) {
            next.prev = prev;
        }
        // If this node is the head or tail, update list references if available
        if (node.list != null) {
            if (node.list.head == node) {
                node.list.head = next;
            }
            if (node.list.tail == node) {
                node.list.tail = prev;
            }
            node.list.size--;
        }
        // Clear node's pointers
        node.prev = null;
        node.next = null;
        return true;
    } catch (Exception e) {
        return false;
    }
}

