private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    Object[] arr = vertices.toArray();
    for (int i = 0; i < size; i++) {
        V v1 = (V) arr[i];
        if (v1 == null) {
            return false;
        }
        for (int j = i + 1; j < size; j++) {
            V v2 = (V) arr[j];
            if (v2 == null) {
                return false;
            }
            if (graph.getEdge(v1, v2) == null) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null) return result;
    for (K keyObj : keys){
        if (keyObj == null){
            result.add(null);
            continue;
        }
        try{
            int key = ((Number)keyObj).intValue();
            int maxLower = Integer.MIN_VALUE;
            boolean found = false;
            for (K otherObj : keys){
                if (otherObj == null) continue;
                int other = ((Number)otherObj).intValue();
                if (other < key && other > maxLower){
                    maxLower = other;
                    found = true;
                }
            }
            result.add(found ? maxLower : null);
        } catch (ClassCastException e){
            result.add(null);
        }
    }
    return result;
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    int count = 0;
    int i = 0;
    if (descriptor.startsWith("(")){
        i = 1;
        while (i < descriptor.length() && descriptor.charAt(i) != ')'){
            i = consumeType(descriptor, i);
            count++;
        }
    }else{
        while (i < descriptor.length()){
            i = consumeType(descriptor, i);
            count++;
        }
    }
    pos -= count;
    if (pos < 0){
        pos = 0;
    }
}
private static int consumeType(String s, int idx){
    char c = s.charAt(idx);
    if (c == 'L'){
        int semicolon = s.indexOf(';', idx);
        return semicolon + 1;
    }else if (c == '['){
        int j = idx;
        while (s.charAt(j) == '['){
            j++;
        }
        return consumeType(s, j);
    }else{
        return idx + 1;
    }
}

