public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    // If relativePath is empty, just return the original path
    if (relativePath.isEmpty()) {
        return path;
    }
    // Determine if the original path is absolute
    boolean leadingSlash = path.startsWith("/");
    // Split the original path into components
    String[] pathParts = path.split("/");
    java.util.List<String> components = new java.util.ArrayList<>();
    for (String part : pathParts) {
        if (!part.isEmpty()) {
            components.add(part);
        }
    }
    // Process the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            // Skip empty or current directory references
            continue;
        } else if (part.equals("..")) {
            // Go up one level if possible
            if (!components.isEmpty()) {
                components.remove(components.size() - 1);
            }
        } else {
            // Normal directory/file component
            components.add(part);
        }
    }
    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (leadingSlash) {
        result.append("/");
    }
    for (int i = 0; i < components.size(); i++) {
        result.append(components.get(i));
        if (i < components.size() - 1) {
            result.append("/");
        }
    }
    // If the result is empty and the original path was absolute, return "/"
    if (result.length() == 0 && leadingSlash) {
        return "/";
    }
    return result.toString();
}

