    if (event == null) {
        return;
    }
    String msg = event.getFormattedMessage();
    if (msg == null) {
        return;
    }
    for (Session session : userSessions) {
        try {
            session.getAsyncRemote().sendText(msg);
        } catch (Exception e) {
            // ignore or log the exception
        }
    }
}

