private void checkIfPackedField() throws IOException {
    // Determine if the current field is a packed repeated field.
    if (currentField != null && currentField.isRepeated() && currentWireType == WireFormat.WIRETYPE_LENGTH_DELIMITED) {
        // Read the length of the packed data.
        int packedLength = readRawVarint32();
        // Update internal state to indicate that a packed field is being read.
        this.packedFieldSize = packedLength;
        this.isPackedField = true;
        this.packedFieldEnd = this.position + packedLength;
    } else {
        this.isPackedField = false;
    }
}

