public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null) {
        return result;
    }
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Assume a static parse method exists on ThreadSnapshot that can parse a line of the file.
            ThreadSnapshot snapshot = ThreadSnapshot.parse(line);
            if (snapshot == null) {
                continue;
            }
            if (timeRanges == null || timeRanges.isEmpty()) {
                result.add(snapshot);
                continue;
            }
            long ts = snapshot.getTimestamp(); // Assume ThreadSnapshot has getTimestamp()
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) {
                    continue;
                }
                long start = range.getStart(); // Assume getStart() returns long
                long end = range.getEnd();     // Assume getEnd() returns long
                if (ts >= start && ts <= end) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    }
    return result;
}
